const p=$('Perfil profesional').first().json.profile;
const norm=s=>String(s||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
const hard=(p.hard_exclusions||[]).map(norm);
const keys=(p.keywords||[]).map(norm);
const roles=[...(p.target_roles||[]),...(p.transition_roles||[])].map(norm);
const allowed=(p.locations_allowed||[]).map(norm);
const now=Date.now(), maxAge=(p.max_age_days||7)*86400000;

function dateMs(v){ if(!v)return null; if(typeof v==="number"){return v<1e12?v*1000:v;} const t=Date.parse(v); return Number.isNaN(t)?null:t; }
function remoteText(t){return /\bremote\b|\bremoto\b|\bteletrabajo\b|\bhybrid\b|\bhibrido\b/.test(t);}
function eurSalary(s){
  const m=String(s||"").match(/(?:€|EUR)\s*([\d.,]+)/i);
  return m?Number(m[1].replace(/\./g,"").replace(",", ".")):null;
}

const out=[];
for(const it of $input.all()){
 const j=it.json, title=String(j.title||"").trim();
 if(!title) continue;
 const text=norm([title,j.company,j.location,j.description].join(" "));
 if(hard.some(x=>x&&text.includes(x))) continue;

 const titleRoles=roles.filter(x=>x&&norm(title).includes(x));
 const matches=[...new Set(keys.filter(x=>x&&text.includes(x)).concat(titleRoles))];
 const loc=norm(j.location);
 const remote=remoteText(text);
 const locOk=allowed.some(x=>x&&loc.includes(x)) || remote;

 if(!locOk && loc && loc!=="no indicada" && loc!=="remote") continue;

 const dt=dateMs(j.published);
 if(dt && now-dt>maxAge) continue;

 const salaryNum=eurSalary(j.salary);
 if(salaryNum && salaryNum < p.minimum_salary_eur) continue;

 const canonical=String(j.url||"").trim();
 const id=j.id || canonical || `${j.source}|${j.company}|${title}|${j.location}`;
 out.push({json:{
   ...j,id,title,company:j.company||"No indicada",location:j.location||"No indicada",
   salary:j.salary||"No indicado",published:j.published||"No indicada",
   description:String(j.description||"").replace(/<[^>]+>/g," ").replace(/\s+/g," ").trim(),
   url:canonical,matches,match_count:matches.length,remote
 }});
}
return out.sort((a,b)=>b.json.match_count-a.json.match_count);

