const order={remote:0,hybrid:1,onsite:2};
const items=$input.all();
items.sort((a,b)=>{
  const pa=order[a.json.work_mode]??3, pb=order[b.json.work_mode]??3;
  if(pa!==pb) return pa-pb;
  return (b.json.score||0)-(a.json.score||0);
});
return items;
